`drainStream` is re-exported from the package entrypoint, but its signature changed from `(stream)` to `(ctx, stream)`, which is a breaking change for downstream users. Consider adding an overload / making `ctx` optional (defaulting to log level OFF) or keeping the old signature and introducing a new API for traced draining.
```suggestion
export async function drainStream(
  stream: Stream.Readable,
): Promise<void>
export async function drainStream(
  ctx: Context,
  stream: Stream.Readable,
): Promise<void>
export async function drainStream(
  ctxOrStream: Context | Stream.Readable,
  maybeStream?: Stream.Readable,
): Promise<void> {
  const hasContext = typeof maybeStream !== 'undefined'
  const stream = (hasContext ? maybeStream : ctxOrStream) as Stream.Readable
  const ctx: Context = hasContext
    ? (ctxOrStream as Context)
    : {
        // default context used when drainStream is called with a single argument (stream only)
        // logging is effectively disabled via log_level OFF
        op: 'drainStream' as unknown as ConnOperation,
        log_level: ClickHouseLogLevel.OFF,
        // log_writer will never be used when log_level is OFF
        log_writer: {} as LogWriter,
        query_id: '',
      }
```

