`RELEASING.md` currently describes promoting the already-published `head` build to `latest` via `npm dist-tag add ... latest`, not republishing from the repo with `npm publish`. If this workflow is meant to automate the documented release flow, it should likely use `npm dist-tag add` for each package (and avoid creating a separate non-`head` version), or the release documentation should be updated to match this new approach.
```suggestion
      - name: Promote published workspace packages to the latest tag
        env:
          NODE_AUTH_TOKEN: ${{ secrets.NPM_TOKEN }}
        run: |
          node <<'EOF'
          const fs = require('fs');
          const path = require('path');
          const { execFileSync } = require('child_process');

          const rootPackage = JSON.parse(fs.readFileSync('package.json', 'utf8'));
          const workspacePatterns = Array.isArray(rootPackage.workspaces)
            ? rootPackage.workspaces
            : (rootPackage.workspaces && Array.isArray(rootPackage.workspaces.packages)
                ? rootPackage.workspaces.packages
                : []);

          const packageJsonPaths = [];

          for (const pattern of workspacePatterns) {
            const match = /^([^*]+)\/\*$/.exec(pattern);
            if (!match) {
              continue;
            }

            const baseDir = match[1].replace(/\/$/, '');
            if (!fs.existsSync(baseDir)) {
              continue;
            }

            for (const entry of fs.readdirSync(baseDir, { withFileTypes: true })) {
              if (!entry.isDirectory()) {
                continue;
              }

              const packageJsonPath = path.join(baseDir, entry.name, 'package.json');
              if (fs.existsSync(packageJsonPath)) {
                packageJsonPaths.push(packageJsonPath);
              }
            }
          }

          for (const packageJsonPath of packageJsonPaths) {
            const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
            if (!pkg.name || !pkg.version) {
              continue;
            }

            const packageVersion = `${pkg.name}@${pkg.version}`;
            console.log(`Promoting ${packageVersion} to latest`);
            execFileSync('npm', ['dist-tag', 'add', packageVersion, 'latest'], { stdio: 'inherit' });
          }
          EOF
```

