```suggestion
    let settled = false
    const stopAndResolve = async (value: boolean) => {
      if (settled) return
      settled = true
      if (intervalId !== undefined) {
        await clearIntervalAsync(intervalId)
      }
      resolve(value)
    }
    // See https://www.npmjs.com/package/set-interval-async#when-should-i-use-setintervalasync
